# Delete the old date directories that are now empty
dirs = apis.file_system.show_directory(access_token=fs_token, directory_path='~/documents/work/meetings/', entry_type='directories')
for d in dirs:
    base = d.rstrip('/').split('/')[-1]
    if base not in ('slides', 'video_recording'):
        print(apis.file_system.delete_directory(access_token=fs_token, directory_path=d))

