steps.code:
# Let's search for each song and find the matching song_id.
# We'll search with title and artist, and pick the first result that matches exactly.
# We'll do this in a loop and print the results for verification.

for song in songs_to_archive:
    query = f"{song['title']} {song['artists']}"
    results = apis.spotify.search_songs(access_token=access_token, query=query, page_limit=5)
    if results:
        # Check if the first result matches exactly
        first = results[0]
        # Check title match
        if first['title'].lower() == song['title'].lower():
            # Check if all artists are present in the result's artists list
            result_artists = [a['name'].lower() for a in first['artists']]
            expected_artists = [a.strip().lower() for a in song['artists'].split(',')]
            if all(any(exp in res for res in result_artists) for exp in expected_artists):
                print(f"Found: {song['title']} -> song_id {first['song_id']}")
            else:
                print(f"Artist mismatch for {song['title']}: expected {expected_artists}, got {result_artists}")
        else:
            print(f"Title mismatch for {song['title']}: got {first['title']}")
    else:
        print(f"No results for {song['title']}")

